<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import { listarAtipicos, notificarAtipico, obtenerAtipico, urlReporteAtipicos } from '../services/atipicos'
import type { CasoAtipico, DistritoAvance } from '../interfaces/atipicos.interface'
const rows=ref<CasoAtipico[]>([]),distritos=ref<DistritoAvance[]>([]),loading=ref(false),saving=ref(false),modal=ref(false),detail=ref<CasoAtipico|null>(null),error=ref(''),success=ref(''),files=ref<File[]>([]),total=ref(0),lastPage=ref(1),summary=reactive({pendientes:0,notificados:0,validados:0});const filters=reactive({criterio:'',distrito_id:'',estado:'pendiente',page:1});const form=reactive({detalle:''});const selectedDistrict=computed(()=>distritos.value.find(x=>x.id===Number(filters.distrito_id)));const districtPercent=(x:DistritoAvance)=>x.total?Math.round(x.validados*100/x.total):0
async function load(page=1){loading.value=true;error.value='';filters.page=page;try{const r=await listarAtipicos(filters);rows.value=r.data;distritos.value=r.distritos;total.value=r.total;lastPage.value=r.last_page;Object.assign(summary,r.resumen)}catch(e){error.value=msg(e)}finally{loading.value=false}}async function open(id:number){error.value='';try{detail.value=await obtenerAtipico(id);form.detalle='';files.value=[];modal.value=true}catch(e){error.value=msg(e)}}function pick(e:Event){files.value=Array.from((e.target as HTMLInputElement).files||[]).slice(0,10)}async function notify(){if(!detail.value)return;if(!files.value.length){error.value='Adjunte al menos una fotografía de la entrega de la notificación.';return}saving.value=true;error.value='';try{const data=new FormData();data.append('detalle',form.detalle);files.value.forEach(x=>data.append('evidencias[]',x));await notificarAtipico(detail.value.id,data);success.value='Notificación registrada y tarea de inspección generada.';modal.value=false;detail.value=null;await load(filters.page)}catch(e){error.value=msg(e)}finally{saving.value=false}}function selectDistrict(id:number){filters.distrito_id=String(id);load(1)}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Medición / Lecturas atípicas</nav><header class="hero"><div class="mark">!</div><div><small>EVAN · CONTROL DE MEDICIÓN</small><h1>Lecturas atípicas</h1><p>Control de desviaciones, notificaciones e inspecciones derivadas.</p></div><div class="stats"><div><b>{{summary.pendientes}}</b><span>Pendientes</span></div><div><b>{{summary.notificados}}</b><span>Notificadas</span></div><div><b>{{summary.validados}}</b><span>Validadas</span></div></div></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="districts"><button v-for="x in distritos" :key="x.id" :class="{active:filters.distrito_id==String(x.id)}" @click="selectDistrict(x.id)"><span>{{x.nombre}}</span><b>{{x.validados}} / {{x.total}}</b><i><em :style="{width:districtPercent(x)+'%'}"></em></i></button></section><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Medidor, suministro o cliente" @keyup.enter="load(1)"></label><label>Estado<select v-model="filters.estado"><option value="pendiente">Pendientes de notificar</option><option value="notificado">Inspección generada</option><option value="validado">Validadas</option><option value="">Todos</option></select></label><button @click="load(1)">Consultar</button><a v-if="filters.distrito_id" :href="urlReporteAtipicos(filters.distrito_id)" target="_blank">Imprimir reporte</a></section><div v-if="loading" class="empty">Cargando lecturas atípicas…</div><div v-else-if="!rows.length" class="empty">No existen lecturas atípicas en esta selección.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id" :class="x.estado"><header><span>{{x.distrito}} · {{x.ruta}}</span><em>{{x.estado==='pendiente'?'Pendiente':x.estado==='notificado'?'Inspección generada':'Validada'}}</em></header><h2>{{x.cliente}}</h2><p>{{x.direccion}}</p><div class="alert"><span>{{x.tipo_error}}</span><b>{{x.desviacion>0?'+':''}}{{x.desviacion}}%</b></div><dl><div><dt>Medidor</dt><dd>{{x.medidor}}</dd></div><div><dt>Suministro</dt><dd>{{x.suministro}}</dd></div><div><dt>Lectura anterior</dt><dd>{{x.lectura_anterior}}</dd></div><div><dt>Lectura actual</dt><dd>{{x.lectura_actual}}</dd></div><div><dt>Consumo</dt><dd>{{x.consumo}} m³</dd></div><div><dt>Promedio</dt><dd>{{x.promedio}} m³</dd></div></dl><footer><button @click="open(x.id)">{{x.estado==='pendiente'?'Notificar usuario':'Ver seguimiento'}}</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}} · {{total}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal&&detail" class="backdrop" @mousedown.self="modal=false"><section class="modal"><header><div><small>MEDIDOR {{detail.medidor}}</small><h2>{{detail.cliente}}</h2><p>{{detail.direccion}}</p></div><button @click="modal=false">×</button></header><div class="reading"><div><span>Anterior</span><b>{{detail.lectura_anterior}}</b></div><div><span>Actual</span><b>{{detail.lectura_actual}}</b></div><div><span>Consumo</span><b>{{detail.consumo}} m³</b></div><div><span>Promedio</span><b>{{detail.promedio}} m³</b></div></div><template v-if="detail.estado==='pendiente'"><div class="notice"><b>Entrega de notificación – Formato 10</b><p>Entregue la notificación al usuario para generar la inspección interna y externa correspondiente.</p></div><label>Evidencias de entrega *<input type="file" multiple accept="image/*" capture="environment" @change="pick"><small>Máximo 10 · {{files.length}} seleccionada(s)</small></label><label>Observaciones<textarea v-model.trim="form.detalle" rows="3" placeholder="Detalle relevante de la notificación"></textarea></label><footer><button class="clear" @click="modal=false">Cancelar</button><button :disabled="saving" @click="notify">{{saving?'Registrando…':'Registrar notificación'}}</button></footer></template><template v-else><section class="tracking"><div><span>Estado</span><b>{{detail.estado==='validado'?'Lectura validada':'Inspección pendiente'}}</b></div><div><span>Expediente</span><b>{{detail.ticket_id?`N.° ${detail.ticket_id}`:'—'}}</b></div><div><span>Detalle</span><b>{{detail.detalle_notificacion||'Sin observaciones'}}</b></div></section><div class="photos"><a v-for="(x,i) in detail.fotografias" :key="i" :href="x" target="_blank"><img :src="x" :alt="`Evidencia ${i+1}`"></a></div><footer><button class="clear" @click="modal=false">Cerrar</button><RouterLink v-if="detail.ticket_id" :to="{name:'comercial-comercializacion-call-center',query:{ticket:detail.ticket_id}}">Ver expediente</RouterLink></footer></template></section></div></div></template>
<style scoped>
