r:#278064}.cards header{display:flex;justify-content:space-between;font-size:.44rem}.cards em{color:var(--a);font-style:normal}.cards h2{margin:10px 0 2px;font-size:.64rem}.cards>article>p{min-height:30px;color:#748187;font-size:.48rem}.alert{padding:8px;display:flex;justify-content:space-between;color:#945c18;background:#fff1dc;font-size:.5rem}.cards dl{display:grid;grid-template-columns:1fr 1fr;gap:6px}.cards dt{color:#89959a;font-size:.4rem}.cards dd{margin:2px 0;font-size:.48rem;font-weight:700}.cards footer button{width:100%}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.pages{display:flex;justify-content:center;align-items:center;gap:8px;font-size:.48rem}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(100%,730px);max-height:94vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:.9rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.reading{margin:13px 0;display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.reading div,.tracking div{padding:9px;background:#f4f1f7}.reading span,.reading b,.tracking span,.tracking b{display:block;font-size:.48rem}.notice{padding:11px;color:#864146;background:#fff0f0;font-size:.52rem}.modal label{display:block;margin:11px 0;font-size:.48rem}.modal label small{display:block;color:#7d898f}.modal footer{display:flex;justify-content:flex-end;gap:6px}.clear{color:#64737a!important;background:#edf1f2!important}.tracking{display:grid;gap:6px}.photos{margin-top:10px;display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.photos img{width:100%;height:120px;object-fit:cover}@media(max-width:850px){.districts{grid-template-columns:1fr 1fr}.cards{grid-template-columns:1fr 1fr}}@media(max-width:540px){.hero{flex-wrap:wrap}.stats{margin-left:0;width:100%}.filters{align-items:stretch;flex-direction:column}.cards,.districts,.reading{grid-template-columns:1fr}}
